dashboard.definition:
{
 "title": "Switch Details",
 "description": "One switch: ports, CPU, memory, PoE, traffic, errors, CDP neighbours, MAC table and syslog. Covers Cribl (sw11-13) and gnmic (IOS-XE, NX-OS) telemetry.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_node": {
   "type": "input.dropdown",
   "title": "Device",
   "dataSources": {
    "primary": "ds_nodes"
   },
   "options": {
    "token": "tk_node",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"node\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"node\") | renameSeries(\"value\")"
   }
  },
  "input_interface": {
   "type": "input.dropdown",
   "title": "Interface",
   "dataSources": {
    "primary": "ds_ifaces"
   },
   "options": {
    "token": "tk_interface",
    "defaultValue": "*",
    "items": ">frame(label, value) | prepend(statics) | objects()"
   },
   "context": {
    "statics": [
     [
      "All"
     ],
     [
      "*"
     ]
    ],
    "label": ">primary | seriesByName(\"interface\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"interface\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "1m",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_nodata": {
   "type": "splunk.table",
   "dataSources": {
    "primary": "ds_nodata"
   },
   "options": {},
   "containerOptions": {
    "visibility": {
     "hideWhenNoData": true
    }
   }
  },
  "viz_ports_up": {
   "type": "splunk.singlevalue",
   "title": "Ports up",
   "dataSources": {
    "primary": "ds_ports_up"
   },
   "options": {
    "majorColor": "#708794",
    "sparklineDisplay": "off",
    "trendDisplay": "off"
   }
  },
  "viz_ports_pct": {
   "type": "splunk.singlevalue",
   "title": "Ports up",
   "dataSources": {
    "primary": "ds_ports_pct"
   },
   "options": {
    "majorColor": "#708794",
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "unit": "%",
    "unitPosition": "after"
   }
  },
  "viz_poe_used": {
   "type": "splunk.singlevalue",
   "title": "PoE used",
   "dataSources": {
    "primary": "ds_poe_used"
   },
   "options": {
    "majorColor": "#708794",
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "unit": "W",
    "unitPosition": "after"
   }
  },
  "viz_poe_free": {
   "type": "splunk.singlevalue",
   "title": "PoE free",
   "dataSources": {
    "primary": "ds_poe_free"
   },
   "options": {
    "majorColor": "#708794",
    "sparklineDisplay": "off",
    "trendDisplay": "off",
    "unit": "W",
    "unitPosition": "after"
   }
  },
  "viz_cpu": {
   "type": "splunk.line",
   "title": "CPU",
   "dataSources": {
    "primary": "ds_cpu"
   },
   "options": {},
   "showProgressBar": true
  },
  "viz_mem": {
   "type": "splunk.line",
   "title": "Memory",
   "dataSources": {
    "primary": "ds_mem"
   },
   "options": {
    "yAxisMax": 100,
    "yAxisMin": 0
   },
   "showProgressBar": true
  },
  "viz_throughput": {
   "type": "splunk.area",
   "title": "Throughput (selected interfaces)",
   "dataSources": {
    "primary": "ds_throughput"
   },
   "options": {},
   "showProgressBar": true
  },
  "viz_errors": {
   "type": "splunk.column",
   "title": "Errors per 5 min (selected interfaces)",
   "dataSources": {
    "primary": "ds_errors"
   },
   "options": {
    "stackMode": "stacked"
   },
   "showProgressBar": true
  },
  "viz_busiest": {
   "type": "splunk.line",
   "title": "Busiest interfaces: peak utilization % (in or out)",
   "dataSources": {
    "primary": "ds_busiest"
   },
   "options": {},
   "showProgressBar": true
  },
  "viz_ifaces": {
   "type": "splunk.table",
   "title": "Interfaces",
   "dataSources": {
    "primary": "ds_ifaces_table"
   },
   "options": {
    "count": 100
   },
   "showProgressBar": true
  },
  "viz_mac": {
   "type": "splunk.table",
   "title": "MAC addresses",
   "dataSources": {
    "primary": "ds_mac"
   },
   "options": {
    "count": 50
   },
   "showProgressBar": true
  },
  "viz_logs": {
   "type": "splunk.table",
   "title": "Syslog",
   "dataSources": {
    "primary": "ds_logs"
   },
   "options": {
    "count": 50
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_nodes": {
   "type": "ds.search",
   "name": "nodes",
   "options": {
    "query": "`mdt_nodes`"
   }
  },
  "ds_ifaces": {
   "type": "ds.search",
   "name": "ifaces",
   "options": {
    "query": "`mdt_if_status($tk_node$)` | `mdt_physical_ports` | fields interface | sort interface"
   }
  },
  "ds_nodata": {
   "type": "ds.search",
   "name": "nodata",
   "options": {
    "query": "`mdt_if_status($tk_node$)` | stats count | where count=0 | eval Note=\"No telemetry for $tk_node$. Switch Details covers switches that stream interface data.\" | fields Note"
   }
  },
  "ds_ports_up": {
   "type": "ds.search",
   "name": "ports_up",
   "options": {
    "query": "`mdt_if_status($tk_node$)` | `mdt_physical_ports` | stats sum(oper_up) as up"
   }
  },
  "ds_ports_pct": {
   "type": "ds.search",
   "name": "ports_pct",
   "options": {
    "query": "`mdt_if_status($tk_node$)` | `mdt_physical_ports` | stats count as total sum(oper_up) as up | eval pct=round(up / total * 100, 0) | fields pct"
   }
  },
  "ds_poe_used": {
   "type": "ds.search",
   "name": "poe_used",
   "options": {
    "query": "`mdt_poe($tk_node$)` | fields used"
   }
  },
  "ds_poe_free": {
   "type": "ds.search",
   "name": "poe_free",
   "options": {
    "query": "`mdt_poe($tk_node$)` | fields free"
   }
  },
  "ds_cpu": {
   "type": "ds.search",
   "name": "cpu",
   "options": {
    "query": "`mdt_cpu($tk_node$)` | timechart span=1m avg(cpu) as \"CPU %\" avg(load) as \"Load average (1 min, NX-OS)\""
   }
  },
  "ds_mem": {
   "type": "ds.search",
   "name": "mem",
   "options": {
    "query": "`mdt_mem($tk_node$)` | timechart span=1m avg(mem) as \"Memory %\""
   }
  },
  "ds_throughput": {
   "type": "ds.search",
   "name": "throughput",
   "options": {
    "query": "`mdt_if_counters($tk_node$,$tk_interface$)` | `mdt_if_rates` | bin _time span=5m | stats avg(in_bps) as in avg(out_bps) as out by _time interface | stats sum(in) as in sum(out) as out by _time | eval \"In (Mb/s)\"=round(in / 1000000, 2), \"Out (Mb/s)\"=round(out / 1000000, 2) | fields - in out"
   }
  },
  "ds_errors": {
   "type": "ds.search",
   "name": "errors",
   "options": {
    "query": "`mdt_if_counters($tk_node$,$tk_interface$)` | `mdt_if_rates` | timechart span=5m sum(in_errs) as \"In errors\" sum(out_errs) as \"Out errors\""
   }
  },
  "ds_busiest": {
   "type": "ds.search",
   "name": "busiest",
   "options": {
    "query": "`mdt_if_counters($tk_node$,$tk_interface$)` | `mdt_if_rates` | join type=left node interface [`mdt_if_status($tk_node$)` | `mdt_physical_ports` | fields node interface speed] | eval util=round(max(in_bps, out_bps) / speed * 100, 2) | timechart span=5m max(util) by interface useother=f where max in top10"
   }
  },
  "ds_ifaces_table": {
   "type": "ds.search",
   "name": "ifaces_table",
   "options": {
    "query": "`mdt_if_status($tk_node$)` | `mdt_physical_ports` | join type=left node interface [`mdt_cdp($tk_node$)` | stats values(neighbour) as neighbour values(remote_interface) as remote_interface by node interface] | search interface=\"$tk_interface$\" | eval Status=case(admin_up==0, \"admin down\", oper_up==1, \"up\", true(), \"down\") | eval Speed=case(speed >= 1000000000, round(speed / 1000000000, 1).\" Gb/s\", speed > 0, round(speed / 1000000, 0).\" Mb/s\") | eval \"Last change\"=strftime(last_change, \"%Y-%m-%d %H:%M\") | eval \"Down for\"=if(oper_up==0 AND isnotnull(last_change), tostring(round(now() - last_change), \"duration\"), null()) | rename interface as Interface, neighbour as \"CDP neighbour\", remote_interface as \"Neighbour port\" | table Interface Status Speed \"Last change\" \"Down for\" \"CDP neighbour\" \"Neighbour port\""
   }
  },
  "ds_mac": {
   "type": "ds.search",
   "name": "mac",
   "options": {
    "query": "`mdt_mac($tk_node$,$tk_interface$)` | sort interface vlan mac | rename interface as Interface, vlan as VLAN, mac as MAC | fields - node"
   }
  },
  "ds_logs": {
   "type": "ds.search",
   "name": "logs",
   "options": {
    "query": "index=cisco_syslog host=\"$tk_node$\" | eval severity=mvindex(severity, 0), message=mvindex(message, 0) | table _time severity message | sort - _time | head 200"
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_node",
   "input_interface"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 2110
    },
    "structure": [
     {
      "item": "viz_nodata",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 1440,
       "h": 80
      }
     },
     {
      "item": "viz_ports_up",
      "type": "block",
      "position": {
       "x": 0,
       "y": 80,
       "w": 360,
       "h": 150
      }
     },
     {
      "item": "viz_ports_pct",
      "type": "block",
      "position": {
       "x": 360,
       "y": 80,
       "w": 360,
       "h": 150
      }
     },
     {
      "item": "viz_poe_used",
      "type": "block",
      "position": {
       "x": 720,
       "y": 80,
       "w": 360,
       "h": 150
      }
     },
     {
      "item": "viz_poe_free",
      "type": "block",
      "position": {
       "x": 1080,
       "y": 80,
       "w": 360,
       "h": 150
      }
     },
     {
      "item": "viz_cpu",
      "type": "block",
      "position": {
       "x": 0,
       "y": 230,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_mem",
      "type": "block",
      "position": {
       "x": 720,
       "y": 230,
       "w": 720,
       "h": 300
      }
     },
     {
      "item": "viz_throughput",
      "type": "block",
      "position": {
       "x": 0,
       "y": 530,
       "w": 720,
       "h": 320
      }
     },
     {
      "item": "viz_errors",
      "type": "block",
      "position": {
       "x": 720,
       "y": 530,
       "w": 720,
       "h": 320
      }
     },
     {
      "item": "viz_busiest",
      "type": "block",
      "position": {
       "x": 0,
       "y": 850,
       "w": 1440,
       "h": 360
      }
     },
     {
      "item": "viz_ifaces",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1210,
       "w": 1440,
       "h": 480
      }
     },
     {
      "item": "viz_mac",
      "type": "block",
      "position": {
       "x": 0,
       "y": 1690,
       "w": 600,
       "h": 420
      }
     },
     {
      "item": "viz_logs",
      "type": "block",
      "position": {
       "x": 600,
       "y": 1690,
       "w": 840,
       "h": 420
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "Switch",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
